import{_ as a,a as l,b as i}from"./chunks/ruankao_20241024174838.COAcL7iZ.js";import{_ as r,o,c as e,at as d}from"./chunks/framework.CY22Hent.js";const p="/assets/ruankao_2025-11-06_115306_326.Bav8KPug.png",_="/assets/ruankao_20250521164608.AHTfM0m4.png",n="/assets/ruankao_20250521164637.CwsKC4mU.png",s="/assets/ruankao_20250521164719.DAzAr6lm.png",x=JSON.parse('{"title":"软件设计师笔记11_标准化和软件知识产权基础知识_精简考点","description":"","frontmatter":{"title":"软件设计师笔记11_标准化和软件知识产权基础知识_精简考点","date":"2025-04-05T00:00:00.000Z","lastUpdated":"2025-11-02T00:00:00.000Z","categories":["软考"],"tags":["软考"]},"headers":[],"relativePath":"blogs/软考/软件设计师笔记11_标准化和软件知识产权基础知识_精简考点.md","filePath":"blogs/软考/软件设计师笔记11_标准化和软件知识产权基础知识_精简考点.md"}'),h={name:"blogs/软考/软件设计师笔记11_标准化和软件知识产权基础知识_精简考点.md"};function u(c,t,b,m,k,g){return o(),e("div",null,[...t[0]||(t[0]=[d('<p>[toc]</p><h1 id="软件设计师笔记11-标准化和软件知识产权基础知识-精简考点" tabindex="-1">软件设计师笔记11_标准化和软件知识产权基础知识_精简考点 <a class="header-anchor" href="#软件设计师笔记11-标准化和软件知识产权基础知识-精简考点" aria-label="Permalink to &quot;软件设计师笔记11_标准化和软件知识产权基础知识_精简考点&quot;">​</a></h1><p><img src="'+p+'" alt="ruankao_2025-11-06_115306_326.png" loading="lazy"></p><h2 id="标准与标准化" tabindex="-1">标准与标准化 <a class="header-anchor" href="#标准与标准化" aria-label="Permalink to &quot;标准与标准化&quot;">​</a></h2><p>标准是标准化活动的产物，其目的和作用都是通过制定和贯彻具体的标准来体现的。</p><p>标准化不是一个孤立的事物，而是一个活动过程。</p><p>标准化活动过程一般包括标准产生、标准实施和标准更新等。</p><h2 id="标准的分类-⭐️" tabindex="-1">标准的分类 ⭐️ <a class="header-anchor" href="#标准的分类-⭐️" aria-label="Permalink to &quot;标准的分类  ⭐️&quot;">​</a></h2><blockquote><p>标准的分类如图所示</p></blockquote><p><img src="'+a+'" alt="ruankao_20241024172951.png" loading="lazy"><img src="'+l+'" alt="ruankao_20241024173018.png" loading="lazy"></p><p><img src="'+i+'" alt="ruankao_20241024174838.png" loading="lazy"></p><table tabindex="0"><thead><tr><th>分类维度</th><th>类型</th><th>示例</th></tr></thead><tbody><tr><td>层级</td><td>国际标准、国家标准、行业标准、企业标准</td><td>ISO、GB、IEEE</td></tr><tr><td>性质</td><td>强制性标准、推荐性标准</td><td>GB（强制）、GB/T（推荐）</td></tr><tr><td>对象</td><td>技术标准、管理标准、工作标准</td><td>产品标准、流程规范</td></tr></tbody></table><h2 id="知识产权保护的对象-⭐️⭐️⭐️" tabindex="-1">知识产权保护的对象 ⭐️⭐️⭐️ <a class="header-anchor" href="#知识产权保护的对象-⭐️⭐️⭐️" aria-label="Permalink to &quot;知识产权保护的对象  ⭐️⭐️⭐️&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>保护对象</th><th>典型例子</th></tr></thead><tbody><tr><td>著作权</td><td>文学、艺术、科学作品</td><td>软件、小说、绘画</td></tr><tr><td>专利权</td><td>发明创造</td><td>技术方案、产品设计</td></tr><tr><td>商标权</td><td>商标、服务标记</td><td>品牌标识、LOGO</td></tr><tr><td>商业秘密</td><td>未披露的信息</td><td>技术配方、客户名单</td></tr></tbody></table><p>另外计算机软件和实用艺术品受著作权保护的同时，权利人还可以通过申请发明专利和外观设计专利获得专利权（工业产权）。</p><h2 id="知识产权基础知识-⭐️" tabindex="-1">知识产权基础知识 ⭐️ <a class="header-anchor" href="#知识产权基础知识-⭐️" aria-label="Permalink to &quot;知识产权基础知识  ⭐️&quot;">​</a></h2><blockquote><p>知识产权的特点如下</p></blockquote><ul><li>无形性：智力成果，无实体形态</li><li>双重性：同一成果可能同时受多种权利保护（如软件可同时受著作权和专利权保护）</li><li>确认性：需依法审查确认</li><li>独占性：权利人享有排他权</li><li>地域性：仅在特定国家/地区有效</li><li>时间性：保护期有限（商标权可续展）</li></ul><h2 id="著作权归属-⭐️" tabindex="-1">著作权归属 ⭐️ <a class="header-anchor" href="#著作权归属-⭐️" aria-label="Permalink to &quot;著作权归属 ⭐️&quot;">​</a></h2><p><img src="'+_+'" alt="ruankao_20250521164608.png" loading="lazy"><img src="'+n+'" alt="ruankao_20250521164637.png" loading="lazy"></p><blockquote><p>总结</p></blockquote><ul><li>若用到了公司的资源，则著作权归属为单位享有，作者享有署名权。</li><li>若没有用到公司的资源，则著作权归属为作者享有。</li></ul><blockquote><p>著作权法不适用于下列情形：</p></blockquote><ul><li>法律、法规或其他具有立法、行政、司法性质的文件，及其官方正式译文；</li><li>时事新闻；</li><li>历法、通用数表、通用表格和公式。</li></ul><h2 id="保护范围和保护对象" tabindex="-1">保护范围和保护对象 <a class="header-anchor" href="#保护范围和保护对象" aria-label="Permalink to &quot;保护范围和保护对象&quot;">​</a></h2><p><img src="'+s+'" alt="ruankao_20250521164719.png" loading="lazy"></p><h2 id="专利权-⭐️" tabindex="-1">专利权 ⭐️ <a class="header-anchor" href="#专利权-⭐️" aria-label="Permalink to &quot;专利权 ⭐️&quot;">​</a></h2><p>若两个申请人分别就相同内容的计算机程序的发明创造，先后向专利行政部门提出申请，先申请人可以获得专利申请权。</p><p>同一天申请的情况处理方式如下:</p><ul><li>①两个申请人作为一件申请的共同申请人:</li><li>②其中一方放弃权利并从另一方得到适当的补偿。</li><li>③如果双方协商不成，则两件申请都不授专利权。</li></ul><h2 id="商标权-⭐️" tabindex="-1">商标权 ⭐️ <a class="header-anchor" href="#商标权-⭐️" aria-label="Permalink to &quot;商标权 ⭐️&quot;">​</a></h2><p>商标权的保护期是可以延长的。</p><p>商标权确定知识产权人的过程。第一原则是：谁先申请谁获得。其次，同时申请时，谁先使用谁获得。</p><p>若A和B公司都是同一天申请商标的情况：</p><ol><li>初步审定并公告使用在先的，驳回其他人的申请</li><li>若双方均未使用或无法证明的，各自协商</li><li>不愿协商或协商不成的，抽签决定。</li><li>不抽签的，视为放弃。</li></ol><p>即同一天申请且均未使用：协商→抽签→不抽签则视为放弃</p><h2 id="侵权判断的特殊要求-⭐️" tabindex="-1">侵权判断的特殊要求 ⭐️ <a class="header-anchor" href="#侵权判断的特殊要求-⭐️" aria-label="Permalink to &quot;侵权判断的特殊要求 ⭐️&quot;">​</a></h2><p>开发软件所用的思想、处理过程、操作方法或者数学概念不受保护。</p><ol><li>著作权自动保护</li></ol><ul><li>中国公民、法人或其他组织的作品，不论是否发表，均享有著作权（★真题必考）</li></ul><ol start="2"><li>合理使用情形</li></ol><ul><li>为个人学习、研究或欣赏使用他人作品</li><li>为介绍、评论某作品引用他人作品</li><li>免费表演他人作品（未向公众收费且未向表演者支付报酬）</li></ul><ol start="3"><li>软件侵权行为</li></ol><ul><li>复制、发布、修改他人软件</li><li>非法拷贝、发布或更改软件的人称为软件盗版者（真题考点）</li></ul><h2 id="法律依据文件-⭐️" tabindex="-1">法律依据文件 ⭐️ <a class="header-anchor" href="#法律依据文件-⭐️" aria-label="Permalink to &quot;法律依据文件 ⭐️&quot;">​</a></h2><table tabindex="0"><thead><tr><th>法律文件</th><th>作用</th></tr></thead><tbody><tr><td>《中华人民共和国著作权法》</td><td>保护著作权的基本法律</td></tr><tr><td>《计算机软件保护条例》</td><td>专门保护软件著作权的行政法规</td></tr><tr><td>《专利法》</td><td>保护发明创造专利权</td></tr><tr><td>《商标法》</td><td>保护商标权</td></tr></tbody></table><p><span style="color:red;">注意：国际上保护软件知识产权的主要方式是实施版权法。</span></p><h2 id="真题" tabindex="-1">真题 <a class="header-anchor" href="#真题" aria-label="Permalink to &quot;真题&quot;">​</a></h2><p>王某是一名软件设计师，按公司规定编写软件文档，并上交公司存档。这些软件文档属于职务作品，且（ 其著作权由公司享有 ）。</p><p>甲软件公司受乙企业委托安排公司软件设计师开发了信息系统管理软件，由于在委托开发合同中未对软件著作权归属作出明确的约定，所以该信息系统管理软件的著作权由（ 甲 ）享有。</p><p>以下关于某委托开发软件的著作权归属的叙述中，正确的是（ 若无书面合同或合同中未明确约定，则该软件的著作权由受托人享有 ）。</p><p>刘某完全利用任职单位的实验材料、实验室和不对外公开的技术资料完成了一项发明。以下关于该发明的权利归属的叙述中，正确的是（ 原则上应归单位所有，但若单位与刘某对成果的归属有特别约定时遵从约定 ）。</p><p>有可能无限期拥有的知识产权是（ 商标权 ）。</p><p>以下有关计算机软件著作权的叙述中，正确的是（ 非法进行拷贝、发布或更改软件的人被称为软件盗版者 ）。</p><p>国际上为保护计算机软件知识产权不受侵犯所采用的主要方式是实施（ 版权法 ）</p><p>甲、 乙两个申请人分别就相同内容的计算机软件发明创造，向国务院专利行政部门门提出专利申请，甲先于乙一日提出，则（ 甲获得该项专利申请权 ）。</p><p>甲、乙两互联网公司于2020年7月7日就各自开发的库存管理软件分别申请“宏达”和“鸿达”商标注册，两个库存管理软件相似，甲第一次使用时间为2019年7月，乙第一次使用时间为2019年5月，此情景下，（ “鸿达” ）能获准注册。</p>',57)])])}const P=r(h,[["render",u]]);export{x as __pageData,P as default};
